import * as THREE from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
import {TransformControls} from './vendor/TransformControls.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {GLTFExporter} from './vendor/GLTFExporter.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const loader=new GLTFLoader(), textureLoader=new THREE.TextureLoader();
let atlas,page,view='art',part=null,currentPath=null,selected=null,request=0,crop=null,cropEnabled=false,wire=false;
let renderer,controls,transform,camera;const scene=new THREE.Scene(), stage=new THREE.Group(),workspace=new THREE.Group();scene.add(stage,workspace);workspace.visible=false;
const status=t=>$('#status').textContent=t;
const message=t=>{status(t);setTimeout(()=>{if($('#status').textContent===t)status('');},6000);};
function dispose(root){root.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material)for(const m of [o.material].flat()){m.map?.dispose();m.dispose();}});}
function clearStage(){stage.children.forEach(dispose);stage.clear();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function linkDownload(path){const a=document.createElement('a');a.href=path;a.download=path.split('/').pop();a.click();}
function assetAllowed(p){return /^assets\/(pages|parts|art)\/s\d{4}(?:_p\d{3})?\.(?:glb|gltf)$/.test(p)||p==='assets/manuscript_all.glb';}
function title(p){return p.label ? 'f'+p.label : p.id;}
function setup3D(){
 try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;$('#viewport').appendChild(renderer.domElement);
 camera=new THREE.PerspectiveCamera(36,1,.001,2000);camera.position.set(0,0,2);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.minDistance=.02;
 scene.add(new THREE.HemisphereLight(0xfff9e3,0x718776,2.4));const light=new THREE.DirectionalLight(0xfff1d1,2);light.position.set(-2,3,5);scene.add(light);
 transform=new TransformControls(camera,renderer.domElement);scene.add(transform.getHelper());transform.addEventListener('dragging-changed',e=>controls.enabled=!e.value);transform.addEventListener('objectChange',syncNumeric);
 new ResizeObserver(()=>{const r=$('#viewport').getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}).observe($('#viewport'));
 renderer.domElement.addEventListener('pointerdown',e=>{renderer.domElement.dataset.down=`${e.clientX},${e.clientY}`;});
 renderer.domElement.addEventListener('pointerup',e=>{if(view!=='workspace'||transform.dragging)return;const d=renderer.domElement.dataset.down?.split(',').map(Number);if(!d||Math.hypot(d[0]-e.clientX,d[1]-e.clientY)>4)return;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObjects(workspace.children,true).find(h=>h.object.visible);if(hit){let o=hit.object;while(o.parent!==workspace)o=o.parent;selectObject(o);}});
 renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera);});return true;
 }catch(e){status('Podgląd 3D wymaga WebGL. Skany i pliki GLB nadal możesz pobrać.');return false;}
}
function fit(root=view==='workspace'?workspace:stage,side=false){if(!camera)return;const box=new THREE.Box3().setFromObject(root);if(box.isEmpty())return;const c=box.getCenter(new THREE.Vector3()),s=box.getSize(new THREE.Vector3()),radius=Math.max(s.y,s.x/camera.aspect,s.z,.05);controls.target.copy(c);camera.position.copy(c).add(new THREE.Vector3(side?radius*1.8:radius*.08,side?radius*.15:0,side?radius*.4:radius*1.85));camera.near=Math.max(.0001,radius/10000);camera.far=Math.max(100,radius*30);camera.updateProjectionMatrix();controls.update();}
function switchView(v){view=v;stage.visible=v!=='workspace';workspace.visible=v==='workspace';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='workspace'){if(selected)transform?.attach(selected);fit();}else{transform?.detach();showModel();}}
async function showModel(){if(view==='workspace')return;const token=++request;currentPath=part?part.model:view==='page'?page.page_model:(page.art_model||page.page_model);if(!renderer)return;status('Ładowanie modelu…');try{const g=await loader.loadAsync(currentPath);if(token!==request){dispose(g.scene);return;}clearStage();stage.add(g.scene);applyWire();fit();status('');}catch(e){status('Nie udało się otworzyć modelu. Możesz pobrać plik GLB.');}}
function applyWire(){[stage,workspace].forEach(root=>root.traverse(o=>{if(o.material)for(const m of [o.material].flat())m.wireframe=wire;}));}
function listPages(){const q=$('#search').value.trim().toLowerCase(),cat=$('#category').value;const rows=atlas.pages.filter(p=>(!cat||p.category===cat)&&JSON.stringify([p.id,title(p),p.scan_number]).toLowerCase().includes(q));$('#visibleCount').textContent=rows.length;$('#pages').replaceChildren(...rows.map(p=>{const b=document.createElement('button');b.className='page'+(p===page?' active':'');b.innerHTML=`<img src="assets/thumbs/${p.id}.jpg" loading="lazy" alt=""><span><b></b><small></small><small>${p.parts.length} fragmentów</small></span>`;b.querySelector('b').textContent=title(p);b.querySelector('small').textContent=p.category;b.onclick=()=>selectPage(p);return b;}));}
function listParts(){const all=document.createElement('button');all.className='part'+(!part?' active':'');all.textContent='Cały rysunek';all.onclick=()=>{part=null;switchView('art');listParts();};$('#parts').replaceChildren(all,...page.parts.map(p=>{const b=document.createElement('button');b.className='part'+(part===p?' active':'');const a=document.createElement('span');a.textContent=p.label;const s=document.createElement('small');s.textContent=p.kind==='source_patch'?'wycinek':'kontur';b.append(a,s);b.onclick=()=>{part=p;view='art';switchView('art');listParts();showRect(p.bbox_norm);};return b;}));}
function selectPage(p){page=p;part=null;crop=null;$('#useCrop').hidden=true;$('#pageTitle').textContent=title(p);$('#categoryName').textContent=p.category;$('#subtitle').textContent=`Skan ${p.scan_number} / ${atlas.pages.length} · ${p.parts.length} fragmentów · CANDIDATE`;$('#sourceId').textContent=p.id;$('#sourceImage').src=`assets/images/${p.id}.jpg`;$('#sourceLink').href=`assets/images/${p.id}.jpg`;$('#cropRect').style.display='none';listPages();listParts();if(view!=='workspace')showModel();}
async function addAsset(path,label,descriptor={}){if(!renderer)return message('Wspólna scena wymaga WebGL.');status('Dodawanie do sceny…');try{const g=await loader.loadAsync(path);const root=new THREE.Group();root.name=label;root.add(g.scene);root.userData={source:path,label,...descriptor};workspace.add(root);switchView('workspace');selectObject(root);renderObjects();applyWire();status('');return root;}catch(e){message('Nie udało się dodać modelu.');throw e;}}
function selectObject(o){selected=o;if(view==='workspace')transform?.attach(o);$('#transform').hidden=!o;renderObjects();syncNumeric();}
function renderObjects(){$('#objects').replaceChildren(...workspace.children.map(o=>{const r=document.createElement('div');r.className='object';const b=document.createElement('button');b.textContent=o.name;b.classList.toggle('active',o===selected);b.onclick=()=>{switchView('workspace');selectObject(o);};const eye=document.createElement('button');eye.textContent=o.visible?'◉':'○';eye.title='Pokaż / ukryj obiekt';eye.onclick=()=>{o.visible=!o.visible;renderObjects();};r.append(b,eye);return r;}));$('#sceneCount').textContent=$('#objectCount').textContent=workspace.children.length;}
function syncNumeric(){if(!selected)return;for(const key of ['position','rotation','scale'])for(let i=0;i<3;i++){const input=$(`#${key}${i}`);if(document.activeElement!==input)input.value=(key==='rotation'?THREE.MathUtils.radToDeg(selected[key].getComponent?selected[key].getComponent(i):selected.rotation[['x','y','z'][i]]):selected[key].getComponent(i)).toFixed(3);}}
for(const [key,label] of [['position','XYZ'],['rotation','Obr.°'],['scale','Skala']]){const row=document.createElement('label');row.textContent=label;for(let i=0;i<3;i++){const input=document.createElement('input');input.type='number';input.step=key==='rotation'?'1':'.01';input.id=key+i;input.setAttribute('aria-label',label+' '+['X','Y','Z'][i]);input.onchange=()=>{const n=Number(input.value);if(!selected||!Number.isFinite(n))return;if(key==='rotation')selected.rotation[['x','y','z'][i]]=THREE.MathUtils.degToRad(n);else selected[key].setComponent(i,key==='scale'?Math.max(.001,n):n);};row.append(input);}$('#numeric').append(row);}
function imageRect(){const el=$('#sourceImage'),r=el.getBoundingClientRect(),ratio=el.naturalWidth/el.naturalHeight,w=Math.min(r.width,r.height*ratio),h=w/ratio;return {left:r.left+(r.width-w)/2,top:r.top+(r.height-h)/2,width:w,height:h};}
function showRect(b){const r=imageRect(),wr=$('#sourceWrap').getBoundingClientRect(),el=$('#cropRect');Object.assign(el.style,{display:'block',left:r.left-wr.left+b[0]*r.width+'px',top:r.top-wr.top+b[1]*r.height+'px',width:(b[2]-b[0])*r.width+'px',height:(b[3]-b[1])*r.height+'px'});}
let start=null;$('#sourceWrap').onpointerdown=e=>{if(!cropEnabled)return;const r=imageRect();start=[THREE.MathUtils.clamp((e.clientX-r.left)/r.width,0,1),THREE.MathUtils.clamp((e.clientY-r.top)/r.height,0,1)];e.currentTarget.setPointerCapture(e.pointerId);};$('#sourceWrap').onpointermove=e=>{if(!start)return;const r=imageRect(),x=THREE.MathUtils.clamp((e.clientX-r.left)/r.width,0,1),y=THREE.MathUtils.clamp((e.clientY-r.top)/r.height,0,1);crop=[Math.min(x,start[0]),Math.min(y,start[1]),Math.max(x,start[0]),Math.max(y,start[1])];showRect(crop);};$('#sourceWrap').onpointerup=()=>{start=null;$('#useCrop').hidden=!crop||crop[2]-crop[0]<.01||crop[3]-crop[1]<.01;};
async function makeCrop(descriptor){const p=atlas.pages.find(p=>p.id===descriptor.scan),b=descriptor.box;if(!p)throw Error('Nieznany skan');const tex=await textureLoader.loadAsync(`assets/images/${p.id}.jpg`);tex.colorSpace=THREE.SRGBColorSpace;const aspect=p.width/p.height,w=(b[2]-b[0])*aspect,h=b[3]-b[1],g=new THREE.BoxGeometry(w,h,.008);const uv=g.attributes.uv;for(let i=0;i<uv.count;i++){uv.setXY(i,b[0]+uv.getX(i)*(b[2]-b[0]),1-b[3]+uv.getY(i)*(b[3]-b[1]));}uv.needsUpdate=true;const mesh=new THREE.Mesh(g,new THREE.MeshStandardMaterial({map:tex,roughness:.92}));mesh.position.set(((b[0]+b[2])/2-.5)*aspect,.5-(b[1]+b[3])/2,.004);mesh.userData={source_scan:p.id,source_sha256:p.sha256,bbox_norm:b,status:'CANDIDATE',depth_basis:'editorial constant thickness'};const root=new THREE.Group();root.name=descriptor.label;root.userData=descriptor;root.add(mesh);return root;}
$('#cropMode').onclick=()=>{cropEnabled=!cropEnabled;$('#cropMode').classList.toggle('active',cropEnabled);$('#cropHint').classList.toggle('show',cropEnabled);};$('#useCrop').onclick=async()=>{if(!crop||!renderer)return;try{const root=await makeCrop({kind:'crop',scan:page.id,box:crop,label:`${title(page)} · własny wycinek`});workspace.add(root);switchView('workspace');selectObject(root);renderObjects();}catch(e){message('Nie udało się utworzyć wycinka.');}};
$('#add').onclick=()=>addAsset(part?part.model:view==='page'?page.page_model:(page.art_model||page.page_model),`${title(page)} · ${part?part.label:view==='page'?'skan':'rysunek'}`);
$('#whole').onclick=()=>addAsset('assets/manuscript_all.glb','Cały manuskrypt · 206 skanów');
$('#downloadCurrent').onclick=async()=>{if(view==='workspace'){if(!selected)return message('Wybierz obiekt we wspólnej scenie.');try{const copy=selected.clone(true);copy.visible=true;copy.updateMatrixWorld(true);const result=await new GLTFExporter().parseAsync(copy,{binary:true,onlyVisible:true});download(new Blob([result],{type:'model/gltf-binary'}),'manuskrypt-obiekt.glb');}catch(e){message('Nie udało się wyeksportować obiektu. Zapisz projekt JSON.');}}else if(currentPath?.endsWith('.gltf')){try{const result=await new GLTFExporter().parseAsync(stage,{binary:true,onlyVisible:false});download(new Blob([result],{type:'model/gltf-binary'}),page.id+'-rysunek.glb');}catch(e){message('Eksport nie powiódł się. Pełne modele są w pakiecie ZIP.');}}else if(currentPath)linkDownload(currentPath);};
$('#front').onclick=()=>{fit();if(camera){camera.position.x=controls.target.x;camera.position.y=controls.target.y;controls.update();}};$('#side').onclick=()=>fit(undefined,true);$('#fit').onclick=()=>fit();$('#wire').onclick=()=>{wire=!wire;$('#wire').classList.toggle('active',wire);applyWire();};
$$('[data-view]').forEach(b=>b.onclick=()=>{part=null;listParts();switchView(b.dataset.view);});$$('[data-mode]').forEach(b=>b.onclick=()=>{transform?.setMode(b.dataset.mode);$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));});
$('#deleteObject').onclick=()=>{if(!selected)return;transform?.detach();workspace.remove(selected);dispose(selected);selected=null;$('#transform').hidden=true;renderObjects();};$('#resetObject').onclick=()=>{if(!selected)return;selected.position.set(0,0,0);selected.rotation.set(0,0,0);selected.scale.set(1,1,1);syncNumeric();fit();};
$('#saveScene').onclick=()=>{const data={format:'voynich-scene',version:1,atlas_version:atlas.version,objects:workspace.children.map(o=>({descriptor:o.userData,position:o.position.toArray(),rotation:[o.rotation.x,o.rotation.y,o.rotation.z],scale:o.scale.toArray(),visible:o.visible}))};download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'manuskrypt-projekt.json');};
$('#loadScene').onclick=()=>$('#sceneFile').click();$('#sceneFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(data.format!=='voynich-scene'||data.version!==1||!Array.isArray(data.objects)||data.objects.length>300)throw Error('Nieobsługiwany format projektu');for(const o of data.objects){if(!o.descriptor||typeof o.descriptor.label!=='string'||!['position','rotation','scale'].every(k=>Array.isArray(o[k])&&o[k].length===3&&o[k].every(Number.isFinite)))throw Error('Niepoprawne współrzędne');if(o.descriptor.kind==='crop'){if(!Array.isArray(o.descriptor.box)||o.descriptor.box.length!==4||!o.descriptor.box.every(x=>Number.isFinite(x)&&x>=0&&x<=1)||o.descriptor.box[2]<=o.descriptor.box[0]||o.descriptor.box[3]<=o.descriptor.box[1])throw Error('Niepoprawny wycinek');}else if(!assetAllowed(o.descriptor.source))throw Error('Nieznane źródło modelu');}status('Wczytywanie projektu…');const pending=[];try{for(const o of data.objects){let root;if(o.descriptor.kind==='crop')root=await makeCrop(o.descriptor);else{const g=await loader.loadAsync(o.descriptor.source);root=new THREE.Group();root.add(g.scene);root.userData=o.descriptor;root.name=o.descriptor.label;}root.position.fromArray(o.position);root.rotation.set(...o.rotation);root.scale.fromArray(o.scale);root.visible=o.visible!==false;pending.push(root);}}catch(e){pending.forEach(dispose);throw e;}transform?.detach();workspace.children.forEach(dispose);workspace.clear();pending.forEach(o=>workspace.add(o));selected=null;$('#transform').hidden=true;renderObjects();switchView('workspace');status('');}catch(err){message('Nie udało się wczytać: '+err.message);}e.target.value='';};
$('#exportScene').onclick=async()=>{if(!workspace.children.length)return message('Najpierw dodaj modele do wspólnej sceny.');const b=$('#exportScene');b.disabled=true;status('Eksportowanie sceny…');try{const copy=workspace.clone(true);copy.visible=true;copy.updateMatrixWorld(true);const result=await new GLTFExporter().parseAsync(copy,{binary:true,onlyVisible:true});download(new Blob([result],{type:'model/gltf-binary'}),'manuskrypt-scena.glb');status('');}catch(e){message('Eksport nie powiódł się. Zapisz projekt JSON, aby zachować pracę.');}finally{b.disabled=false;}};
$('#search').oninput=listPages;$('#category').onchange=listPages;
try{atlas=await(await fetch('assets/atlas.json')).json();$('#count').textContent=atlas.pages.length;$('#partsCount').textContent=atlas.pages.reduce((s,p)=>s+p.parts.length,0);for(const c of [...new Set(atlas.pages.map(p=>p.category))]){const o=document.createElement('option');o.value=o.textContent=c;$('#category').append(o);}setup3D();selectPage(atlas.pages.find(p=>p.id==='s0004')||atlas.pages[0]);}catch(e){status('Nie udało się wczytać katalogu. Odśwież stronę.');}
if(navigator.modelContext?.registerTool){navigator.modelContext.registerTool({name:'read_atlas_state',description:'Read the selected manuscript scan and objects in the local 3D workspace.',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify({scan:page?.id,view,objects:workspace.children.map(o=>({name:o.name,source:o.userData.source,position:o.position.toArray()}))})}]})});}
